public class ProducerConsumerQueue<T> {
    private final java.util.Queue<T> queue = new java.util.LinkedList<>();
    private final int capacity = 5;

    public synchronized void produce(T item) throws InterruptedException {
        while (queue.size() == capacity) {
            // Releases monitor and waits safely; protects against spurious wakeups
            wait();
        }
        queue.offer(item);
        notifyAll(); // Wake up any waiting consumers
    }

    public synchronized T consume() throws InterruptedException {
        while (queue.isEmpty()) {
            wait();
        }
        T item = queue.poll();
        notifyAll(); // Wake up any waiting producers
        return item;
    }
}
